  Exercise(id:"python-c1-t0-classwork-1-v1", topic:"python-c1-t0", category:"Classwork", type:"code", title:"Numeric comparison", prompt:"Read two valid integers and output whether the first is greater than or equal to the second. Print one Boolean line.", tests:[{"input":["5","5"],"expected":"True","harness":"","comparison":"normalized"},{"input":["4","5"],"expected":"False","harness":"","comparison":"normalized"},{"input":["12","3"],"expected":"True","harness":"","comparison":"normalized"},{"input":["-2","-3"],"expected":"True","harness":"","comparison":"normalized"}], hints:["Check the equality boundary."], required:false, filename:"learner.py"),
