 failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["  ","5","1"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","5","6"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","-1","0"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","5","-1"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"}], hints:["Plan invalid cases before the valid report."], required:false, filename:"main.py"),
